// 计数排序
void CountSort(int A[], int B[], int n, int k){
  int i,C[k];           //辅助数组C的⻓度取决于待排序元素取值范围[0, k)
  for(i=0;i<k;i++)      //初始化计数数组
    C[i]=0;         
  for(i=0;i<n;i++)      //Step1：遍历待排序数组，统计每个关键字的出现次数
    C[A[i]]++;      
  for(i=1;i<k;i++)      //Step2：再次处理辅助数组，统计不⼤于 i 的元素个数
    C[i]=C[i]+C[i-1];   //C[i]保存的是⼩于或等于 i 的元素个数
  for(i=n-1;i>=0;i--){  //Step3：利⽤辅助数组C实现计数排序（从后往前处理）
    C[A[i]]=C[A[i]]-1; 
    B[C[A[i]]]=A[i];  //将元素 A[i]放在输出数组 B[]的正确位置上
  }
}

