计数排序的代码实现 

1. 实战版本（更通⽤，以下代码可直接运⾏）

#include <stdio.h>
#include <stdlib.h>
void counting_sort(int A[], int n) {
    // 1. 找到数组 A 中的最⼤值和最⼩值
    int max = A[0];
    int min = A[0];
    for (int i = 1; i < n; i++) {
        if (A[i] > max) {
            max = A[i];
        }
        if (A[i] < min) {
            min = A[i];
        }
    }
    // 2. 创建计数数组
    int k = max - min + 1;
    int* C = (int*)calloc(k, sizeof(int));  // 动态分配内存
    // 3. 统计每个元素出现的次数
    for (int i = 0; i < n; i++) {
        C[A[i] - min]++;
    }
    // 4. 将计数数组转化为累加数组
    for (int i = 1; i < k; i++) {
        C[i] += C[i - 1];
    }
    // 5. 构建输出数组
    int* B = (int*)malloc(n * sizeof(int));  // 动态分配输出数组
    for (int i = n - 1; i >= 0; i--) {  //从后往前处理，确保稳定性
        B[C[A[i] - min] - 1] = A[i];
        C[A[i] - min]--;
    }
    // 6. 将输出数组B拷⻉回原数组A
    for (int i = 0; i < n; i++) {
        A[i] = B[i];
    }
    // 7. 释放内存
    free(C);
    free(B);
}

